-- "Listen to this article": one narration per blog post, generated by the
-- worker with ElevenLabs. The MP3 lives in object storage (storageKey); the
-- row holds duration, chapters and waveform peaks for the player.

CREATE TABLE "blog_audio" (
    "id" TEXT NOT NULL,
    "postId" TEXT NOT NULL,
    "status" TEXT NOT NULL DEFAULT 'ready',
    "narrationHash" TEXT NOT NULL,
    "storageKey" TEXT,
    "voiceId" TEXT NOT NULL,
    "modelId" TEXT NOT NULL,
    "durationMs" INTEGER NOT NULL DEFAULT 0,
    "byteSize" INTEGER NOT NULL DEFAULT 0,
    "characters" INTEGER NOT NULL DEFAULT 0,
    "chapters" JSONB NOT NULL DEFAULT '[]',
    "peaks" JSONB NOT NULL DEFAULT '[]',
    "error" TEXT,
    "attempts" INTEGER NOT NULL DEFAULT 0,
    "generatedAt" TIMESTAMP(3),
    "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updatedAt" TIMESTAMP(3) NOT NULL,

    CONSTRAINT "blog_audio_pkey" PRIMARY KEY ("id")
);

CREATE UNIQUE INDEX "blog_audio_postId_key" ON "blog_audio"("postId");

ALTER TABLE "blog_audio" ADD CONSTRAINT "blog_audio_postId_fkey" FOREIGN KEY ("postId") REFERENCES "blog_post"("id") ON DELETE CASCADE ON UPDATE CASCADE;

ALTER TABLE "blog_audio" ENABLE ROW LEVEL SECURITY;
